 dict(section="O wrapper de retry", type="code", title="inSerializable: o loop de retry em NestJS", code=[
   "const RETRYABLE = new Set(['40001', '40P01']);",
   "for (let attempt = 1; ; attempt++) {",
   "  const client = await pool.connect();",
   "  try {",
   "    await client.query('BEGIN ISOLATION LEVEL SERIALIZABLE');",
   "    const result = await work(client);   // relê os saldos a cada tentativa",
   "    await client.query('COMMIT');  return result;",
   "  } catch (err: any) {",
   "    await client.query('ROLLBACK').catch(() => undefined);",
   "    if (!RETRYABLE.has(err.code) || attempt >= maxAttempts) throw err;",
   "    await sleep(Math.random() * 20 * attempt);",
   "  } finally { client.release(); }",
   "}"], hl=[5, 6, 9],
   notes=[("O erro pode vir num UPDATE ou no COMMIT: o catch cobre os dois", "amber"),
          ("Dado lido não vale até o commit: nada de push com saldo do meio do caminho", "red")], beats=[
  (1, "Num serviço NestJS, o wrapper fica assim. Abre a transação serializable, roda o trabalho, que relê os saldos a cada tentativa, e faz commit. Se der quatro zero zero zero um ou deadlock, rollback, uma pequena espera aleatória, e tenta de novo, até o limite."),
  (2, "Repare que o erro pode chegar num UPDATE ou no próprio COMMIT, e o catch cobre os dois."),
  (3, "E uma regra sutil: dados lidos numa transação serializable só valem depois do commit. Não mande uma push notification com um saldo lido no meio do caminho."),
  ("P", "Pergunta: qual SQLSTATE marca uma falha de serialização, e o que exatamente você repete no retry?"),
  (3, "Quatro zero zero zero um. Você repete a transação inteira, incluindo as leituras e a lógica que decide o que gravar."),
 ]),
